def bubble_sort(xs):
    for i in range(len(xs)):
        for j in range(1, len(xs)-i):
            if xs[j-1] > xs[j]:
                xs[j-1], xs[j] = xs[j], xs[j-1]
    return xs

def second_largest(xs):
    s = len(set(xs))
    if s < 2:
        return None
    points = bubble_sort(xs)
